        q("eng-summary-005","eng-summary-synthesis","Before writing a summary, a reader should first:",listOf("Identify the main points","Count every adjective","Copy the final paragraph","Choose a title only"),0,"Identifying essential points is the first step in producing an accurate summary."),
        q("eng-vocab-001","eng-vocabulary-context","Choose the word nearest in meaning to 'concise'.",listOf("Brief","Confused","Lengthy","Uncertain"),0,"Concise means brief and expressed in few words."),
