        q("eng-vocab-003","eng-vocabulary-context","Which pair consists of homophones?",listOf("cat and cut","flour and flower","ship and sheep","thin and then"),1,"Flour and flower have the same pronunciation but different meanings and spellings."),
        q("eng-vocab-004","eng-vocabulary-context","The expression 'to break the ice' means to:",listOf("Destroy frozen water","Begin a friendly conversation in an awkward situation","End a relationship","Make a promise"),1,"The idiom means to reduce social tension and make people feel more comfortable."),
        q("eng-vocab-005","eng-vocabulary-context","'The wind whispered through the trees' is an example of:",listOf("Personification","Alliteration only","Literal description","Onomatopoeia"),0,"Personification gives a human action, whispering, to the wind."),
        q("eng-grammar-001","eng-grammar-structures","Choose the correct verb: 'Neither of the boys ___ present.'",listOf("are","were","is","have"),2,"Neither is treated as singular in this construction, so the correct verb is is."),
