        q("eng-grammar-004","eng-grammar-structures","Choose the correct sentence.",listOf("The list of items are long.","The list of items is long.","The list of items were long.","The list of items have long."),1,"The head noun list is singular, so the verb is takes singular agreement."),
        q("eng-grammar-005","eng-grammar-structures","Choose the correct question tag: 'She is ready, ___?'",listOf("is she","isn't she","does she","wasn't she"),1,"A positive statement with is normally takes the negative tag isn't she?"),
        q("eng-mechanics-001","eng-usage-mechanics","Which sentence uses the apostrophe correctly?",listOf("The girls bag is missing.","The girl's bag is missing.","The girls's bag is missing.","The girl bag's is missing."),1,"The singular possessive girl's shows that the bag belongs to one girl."),
        q("eng-mechanics-002","eng-usage-mechanics","Which punctuation mark can join two closely related independent clauses?",listOf("Apostrophe","Semicolon","Hyphen only","Question mark"),1,"A semicolon can join closely related independent clauses."),
        q("eng-mechanics-003","eng-usage-mechanics","Which sentence contains a comma splice?",listOf("I arrived early, and I waited.","I arrived early; I waited.","I arrived early, I waited.","I arrived early because I waited."),2,"A comma splice joins two independent clauses with only a comma."),
        q("eng-mechanics-004","eng-usage-mechanics","Choose the correct completion: 'The committee reached ___ decision.'",listOf("it's","its","it is","its'"),1,"Its is the possessive determiner; it's means it is or it has."),
        q("eng-mechanics-005","eng-usage-mechanics","Choose the correct preposition: 'She is interested ___ science.'",listOf("on","at","in","for"),2,"The standard collocation is interested in."),
