        q("eng-oral-002","eng-oral-sounds","The vowel sound in the word 'my' is commonly classified as a:",listOf("Monophthong","Diphthong","Plosive","Nasal consonant"),1,"The vowel in my glides between two vowel qualities and is a diphthong."),
        q("eng-oral-003","eng-oral-sounds","The sounds /p/ and /b/ differ mainly in:",listOf("Voicing","Place of articulation","Both being vowels","Number of syllables"),0,"Both are bilabial plosives, but /p/ is voiceless and /b/ is voiced."),
        q("eng-oral-004","eng-oral-sounds","Which pair rhymes?",listOf("light and night","cat and cut","food and foot","rough and through"),0,"Light and night share the same stressed vowel and final consonant sounds."),
        q("eng-oral-005","eng-oral-sounds","Which pair contains a consonant cluster at the beginning of the word?",listOf("street","apple","open","idea"),0,"Street begins with the consonant cluster /str/."),
        q("eng-stress-001","eng-stress-intonation","In standard pronunciation, the noun 'REcord' is stressed on the:",listOf("First syllable","Second syllable","Last letter","Both syllables equally"),0,"The noun REcord normally has first-syllable stress; the verb reCORD has second-syllable stress."),
        q("eng-stress-002","eng-stress-intonation","Word stress refers to:",listOf("Prominence given to a syllable","The number of letters in a word","The spelling of a word","A punctuation mark"),0,"Word stress is the prominence given to one syllable in a word."),
        q("eng-stress-003","eng-stress-intonation","Rising intonation is common in many:",listOf("Yes/no questions","Declarative statements only","Written headings","Plural nouns"),0,"Many yes/no questions use rising intonation, although context can affect the pattern."),
        q("eng-stress-004","eng-stress-intonation","In 'I wanted the BLUE pen', stressing BLUE highlights:",listOf("The speaker's identity","The colour requested","The time of the request","The number of pens"),1,"The stress on BLUE contrasts the requested colour with other possible colours."),
        q("eng-stress-005","eng-stress-intonation","The weak vowel sound /ə/ is called:",listOf("Schwa","Diphthong","Plosive","Trill"),0,"Schwa is a common reduced vowel in unstressed syllables.")
